pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;

    function setUp() public {
        c = new airPort();
    }

    function testFuzz_property(address from, address to, uint256 v) public {
        vm.assume(to != address(0));
        address[] memory tos = new address[](1);
        tos[0] = to;

        Recorder rec = new Recorder();
        bool ok = c.transfer(from, address(rec), tos, v);

        assertTrue(ok && rec.from() == from && rec.to() == to && rec.amount() == v);
    }
}

contract Recorder {
    address public from;
    address public to;
    uint256 public amount;

    function transferFrom(address _from, address _to, uint256 _v) external returns (bool) {
        from = _from;
        to = _to;
        amount = _v;
        return true;
    }
}
